                    if (checkSweepEnabled) {
                        check.step(levels, now)?.let { onSweepUpdate?.invoke(SweepProcess.AUTO_CHECK, it) }
                    }
                }
                delay(SweeperProcessor.TICK_MS)
            }
        }
    }

